const filterLabels = {
  todos: 'Todos',
  institucional: 'Institucional',
  ecommerce: 'E-commerce',
  landing: 'Landing Page',
  sistema: 'Sistema'
};

export function initFilters(el, onChange) {
  let ativo = 'todos';

  function render() {
    el.innerHTML = '';
    Object.keys(filterLabels).forEach(function (chave) {
      const btn = document.createElement('button');
      btn.className = 'filter-btn' + (chave === ativo ? ' active' : '');
      btn.type = 'button';
      btn.textContent = filterLabels[chave];
      btn.addEventListener('click', function () {
        ativo = chave;
        render();
        if (onChange) onChange(chave);
      });
      el.appendChild(btn);
    });
  }

  render();
}

