componentes.js:
export function initNav() {
  const navSections = ['top', 'portfolio', 'servicos', 'sobre', 'faq', 'contato'];
  const navLinks = document.querySelectorAll('[data-section]');

  function setActiveNav(id) {
    navLinks.forEach(function (a) {
      a.classList.toggle('active', a.getAttribute('data-section') === id);
    });
  }

  // A seção que cruza a faixa central da tela é a ativa. Marcar pelo clique
  // erraria assim que a pessoa rolasse por conta própria.
  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) {
      if (e.isIntersecting) setActiveNav(e.target.id);
    });
  }, { rootMargin: '-45% 0px -45% 0px' });

  navSections.forEach(function (id) {
    const el = document.getElementById(id);
    if (el) observer.observe(el);
  });

  const menuToggle = document.getElementById('menuToggle');
  menuToggle.addEventListener('click', function () {
    document.body.classList.toggle('menu-open');
  });
  document.querySelectorAll('.mobile-nav a').forEach(function (a) {
    a.addEventListener('click', function () {
      document.body.classList.remove('menu-open');
    });
  });
}

