// A linha só se desenha quando a seção entra na tela — e uma vez só, senão
// a página fica piscando pra quem rola de volta.
export function initProcesso() {
  const secao = document.getElementById('processo');
  if (!secao || !('IntersectionObserver' in window)) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-revealed');
      observer.unobserve(entry.target);
    });
  }, { rootMargin: '0px 0px -12% 0px', threshold: 0.05 });

  observer.observe(secao);
}

