export function initFaq(faqs) {
  const faqList = document.getElementById('faqList');
  let openIndex = 0;

  function render() {
    faqList.innerHTML = '';
    faqs.forEach(function (item, i) {
      const isOpen = i === openIndex;
      const row = document.createElement('div');
      row.className = 'faq-item';
      row.innerHTML =
        '<div class="faq-row">' +
          '<span class="faq-q sora' + (isOpen ? ' open' : '') + '">' + item.q + '</span>' +
          '<span class="faq-sign mono">' + (isOpen ? '−' : '+') + '</span>' +
        '</div>' +
        '<div class="faq-a' + (isOpen ? ' open' : '') + '">' + item.a + '</div>';
      row.addEventListener('click', function () {
        openIndex = isOpen ? -1 : i;
        render();
      });
      faqList.appendChild(row);
    });
  }

  render();
}

