/* Só o card do centro fica em cor cheia; os outros recuam para o fundo. */
.cf-card::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: rgba(5, 5, 5, 0.45);
  transition: background 0.3s ease;
}
.cf-card.is-center::after { background: transparent; }
.cf-card.is-center { border-color: var(--accent); }

.cf-nav {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 200;
  width: 44px; height: 44px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: rgba(10, 10, 10, 0.75); backdrop-filter: blur(6px);
  border: 1px solid var(--border-alt); color: #fff;
  transition: background 0.2s ease, border-color 0.2s ease;
}
.cf-nav:hover { background: var(--accent); border-color: transparent; color: var(--bg); }
.cf-prev { left: 8px; }
.cf-next { right: 8px; }

.cf-caption { margin-top: 28px; text-align: center; }
.cf-caption-title { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 20px; letter-spacing: -0.02em; }
.cf-caption-sub { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--accent); letter-spacing: 0.15em; text-transform: uppercase; margin-top: 8px; }

.cf-dots { display: flex; justify-content: center; flex-wrap: wrap; gap: 8px; margin-top: 24px; }
.cf-dot {
  width: 7px; height: 7px; border-radius: 50%; padding: 0;
  background: var(--text); border: 0; opacity: 0.25;
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.cf-dot[aria-current="true"] { opacity: 1; background: var(--accent); transform: scale(1.25); }

.cf-hint {
  margin-top: 18px; text-align: center;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-dimmer);
  letter-spacing: 0.12em; text-transform: uppercase;
}

@media (max-width: 700px) {
  .cf { --cf-card: 62vw; }
  .cf-nav { display: none; }
}

