// A posição é uma única fonte de verdade: `pos`, o índice fracionário do
// card que está no centro. Tudo o mais é derivado dela.

const ROTATE = 44;      // graus que o primeiro vizinho inclina
const DEPTH = 0.6;      // quanto ele recua, em fração da largura do card
const FALLOFF = 0.56;   // expoente da distância; abaixo de 1 a inclinação alivia
const FADE = 0.1;       // opacidade perdida por card de distância
const GAP = 0.05;       // espaço entre cards, em fração da largura
const PERSPECTIVE = 3;  // distância do observador, em múltiplos da largura

export function createCoverflow(config) {
  const frame = config.frame;
  const track = config.track;
  const slides = config.slides;
  const onSelect = config.onSelect;
  const count = slides.length;
  if (!count) return null;

  const cards = [];
  let pos = 0;        // onde estamos
  let target = 0;     // para onde a animação vai
  let width = 0;
  let raf = null;
  let selected = -1;
  let drag = null;

  track.innerHTML = '';
  slides.forEach(function (slide, i) {
    const card = document.createElement(slide.url ? 'a' : 'div');
    card.className = 'cf-card';
    if (slide.url) {
      card.href = slide.url;
      card.target = '_blank';
      card.rel = 'noopener noreferrer';
    }
    card.setAttribute('role', 'group');
    card.setAttribute('aria-label', (i + 1) + ' de ' + count);
    card.innerHTML =
      '<img src="' + slide.image + '" alt="Captura do site ' + slide.title + '" draggable="false" loading="lazy">';
    // Um arrasto termina em click; sem isso, girar o carrossel abriria o site.
    card.addEventListener('click', function (e) {
      if (card.dataset.arrastou === '1') {
        e.preventDefault();
        card.dataset.arrastou = '';
      }
    });
    track.appendChild(card);
    cards.push(card);
  });

  function indexAt(p) {
    return ((Math.round(p) % count) + count) % count;
  }

  // Pinta direto no DOM: sessenta atualizações por segundo não passam por
  // lugar nenhum além do style de cada card.
  function paint() {
    if (!width) return;
    const pitch = width * (1 + GAP);

    for (let i = 0; i < count; i++) {
      // Dobra a distância pelo lado mais curto do anel. É todo o mecanismo
      // de loop — sem clonar nó, sem remexer o DOM.
      let offset = i - pos;
      offset = ((offset % count) + count) % count;
      if (offset > count / 2) offset -= count;

      const distance = Math.abs(offset);
      const ramp = Math.pow(distance, FALLOFF);
      // Limitado antes de ficar de perfil, para um card distante nunca virar
      // as costas.
      const tilt = Math.min(ROTATE * ramp, 82) * Math.sign(offset);

      cards[i].style.transform =
        'translateX(calc(-50% + ' + (offset * pitch) + 'px)) ' +
        'translateZ(' + (-DEPTH * width * ramp) + 'px) ' +
        'rotateY(' + (-tilt) + 'deg)';

      // O card é teletransportado para o outro lado do anel exatamente a meia
      // volta, então precisa já ter sumido quando chegar lá.
      const edge = Math.min(1, Math.max(0, count / 2 - distance));
      cards[i].style.opacity = String(Math.max(0, 1 - FADE * distance) * edge);
      cards[i].style.zIndex = String(100 - Math.round(distance));
      cards[i].classList.toggle('is-center', Math.round(distance) === 0);
    }
  }

  function anunciar(i) {
    if (i === selected) return;
    selected = i;
    if (onSelect) onSelect(i, slides[i]);
  }

  function settle(destino) {
    if (raf !== null) cancelAnimationFrame(raf);
    target = destino;
    anunciar(indexAt(destino));

    function step() {
      const falta = target - pos;
      if (Math.abs(falta) < 0.0004) {
        pos = target;
        paint();
        raf = null;
        return;
      }
      // ease-out exponencial, não mola. Só troque por mola se a parada
      // precisar passar do ponto e voltar.
      pos += falta * 0.16;
      paint();
      raf = requestAnimationFrame(step);
    }
    raf = requestAnimationFrame(step);
  }

  function goTo(i) {
    // Vai pelo lado mais curto, em vez de desenrolar o anel inteiro.
    settle(i + Math.round((target - i) / count) * count);
  }

  function nudge(by) {
    settle(Math.round(target) + by);
  }

  frame.addEventListener('pointerdown', function (e) {
    if (raf !== null) { cancelAnimationFrame(raf); raf = null; }
    frame.setPointerCapture(e.pointerId);
    target = pos;
    drag = { id: e.pointerId, x: e.clientX, pos: pos, v: 0, t: performance.now(), andou: 0 };
  });

  frame.addEventListener('pointermove', function (e) {
    if (!drag || drag.id !== e.pointerId) return;
    const pitch = width * (1 + GAP);
    if (!pitch) return;
    const agora = performance.now();
    const antes = pos;
    const dx = e.clientX - drag.x;
    drag.andou = Math.max(drag.andou, Math.abs(dx));
    pos = drag.pos - dx / pitch;
    // Cards por segundo, para o arremesso.
    drag.v = ((pos - antes) / Math.max(agora - drag.t, 1)) * 1000;
    drag.t = agora;
    anunciar(indexAt(pos));
    paint();
  });

  function endDrag(e) {
    if (!drag || drag.id !== e.pointerId) return;
    const andou = drag.andou;
    const v = drag.v;
    drag = null;
    if (andou > 6) {
      const alvo = cards[indexAt(pos)];
      if (alvo) alvo.dataset.arrastou = '1';
    }
    // Deixa o impulso carregar, mas nunca mais que dois cards.
    const carregado = Math.max(-2, Math.min(2, v * 0.18));
    settle(Math.round(pos + carregado));
  }
  frame.addEventListener('pointerup', endDrag);
  frame.addEventListener('pointercancel', endDrag);

  frame.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowLeft') { e.preventDefault(); nudge(-1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); nudge(1); }
  });

  // A largura do card manda no passo, na profundidade e na perspectiva, então
  // é a única coisa que vale medir — e só quando a caixa muda de tamanho.
  function measure() {
    if (!cards[0]) return;
    width = cards[0].offsetWidth;
    frame.style.perspective = (width * PERSPECTIVE) + 'px';
    paint();
  }
  const observer = new ResizeObserver(measure);
  observer.observe(frame);
  measure();
  anunciar(0);

  return {
    goTo: goTo,
    nudge: nudge,
    destroy: function () {
      observer.disconnect();
      if (raf !== null) cancelAnimationFrame(raf);
    }
  };
}

