/* Os campos não acompanham a largura total: linha de input muito longa é
   ruim de ler e de preencher. */
.ob-step { max-width: 760px; width: 100%; }

.ob-field { display: block; margin-bottom: 26px; }
.ob-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.ob-label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 8px; }
.ob-req { font-family: 'JetBrains Mono', monospace; font-size: 10px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent); margin-left: 8px; }
.ob-opt { font-family: 'JetBrains Mono', monospace; font-size: 10px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-dimmer); margin-left: 8px; }
.ob-help { display: block; font-size: 13px; line-height: 1.5; color: var(--text-dim); margin-top: 8px; }
.ob-warn {
  display: block; font-size: 13px; line-height: 1.5; color: #fbbf24; margin-top: 8px;
  border-left: 2px solid #fbbf24; padding-left: 10px;
}

.ob-field input[type=text], .ob-field input[type=email], .ob-field input[type=tel],
.ob-field input[type=url], .ob-field select, .ob-field textarea {
  width: 100%; padding: 13px 14px;
  background: var(--bg-alt); color: var(--text);
  border: 1px solid var(--border-alt); border-radius: 4px;
  font-family: 'Manrope', sans-serif; font-size: 15px;
  transition: border-color 0.2s ease;
}
.ob-field textarea { resize: vertical; }
.ob-field input:focus, .ob-field select:focus, .ob-field textarea:focus {
  outline: none; border-color: var(--accent);
}
.ob-field input::placeholder, .ob-field textarea::placeholder { color: var(--text-dimmer); }

.ob-field input[type=file] {
  width: 100%; padding: 13px 14px;
  background: var(--bg-alt); border: 1px dashed var(--border-alt); border-radius: 4px;
  font-family: 'JetBrains Mono', monospace; font-size: 12px; color: var(--text-dim);
}
.ob-field input[type=file]::file-selector-button {
  margin-right: 14px; padding: 8px 14px;
  background: transparent; color: var(--accent);
  border: 1px solid var(--border-alt); border-radius: 3px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase;
  cursor: pointer;
}

.ob-checks { display: flex; flex-wrap: wrap; gap: 10px 22px; margin-top: 4px; }
.ob-checks label { display: flex; align-items: center; gap: 8px; font-size: 15px; color: var(--text-muted); cursor: pointer; }
.ob-checks input { accent-color: var(--accent); width: 16px; height: 16px; }

@media (max-width: 700px) {
  .ob-row { grid-template-columns: 1fr; }
}

.ob-progress-wrap {
  position: sticky; top: 0; z-index: 10;
  background: var(--bg); border-bottom: 1px solid var(--border-alt); padding: 18px 40px;
}
.ob-progress-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 12px; }
.ob-progress-top span { font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--text-dim); }
.ob-save-state { color: var(--accent) !important; }
.ob-progress { height: 3px; background: var(--border-alt); border-radius: 2px; overflow: hidden; }
.ob-progress-bar { height: 100%; width: 0; background: var(--accent); transition: width 0.35s ease; }

@media (max-width: 700px) {
  .ob-progress-wrap { padding-left: 20px; padding-right: 20px; }
}

.demo-controles { display: flex; gap: 12px; padding: 32px 40px; }
.demo-controles button {
  padding: 12px 22px; background: transparent; color: var(--text);
  border: 1px solid var(--border-alt); border-radius: 4px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase;
}
.demo-controles button:hover { border-color: var(--accent); color: var(--accent); }

componentes.js:
export function initProgresso(passos) {
  const rotulo = document.getElementById('obPasso');
  const barra = document.getElementById('obBarra');
  let atual = 0;

  function pintar() {
    rotulo.textContent = 'Passo ' + (atual + 1) + ' de ' + passos.length + ' · ' + passos[atual];
    barra.style.width = (((atual + 1) / passos.length) * 100) + '%';
  }

  function ir(delta) {
    atual = Math.min(Math.max(atual + delta, 0), passos.length - 1);
    pintar();
  }

  pintar();
  return { ir: ir };
}

