export function initToggle(el, onChange) {
  const botoes = Array.prototype.slice.call(el.querySelectorAll('.ob-toggle-btn'));
  botoes.forEach(function (btn, i) {
    btn.addEventListener('click', function () {
      botoes.forEach(function (b) { b.classList.remove('is-active'); });
      btn.classList.add('is-active');
      if (onChange) onChange(i, btn.textContent);
    });
  });
}

