.ob-picker { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; padding: 40px; }
.ob-picker-card {
  display: flex; flex-direction: column; gap: 10px;
  background: var(--bg-alt); border: 1px solid var(--border-alt); border-radius: 6px;
  padding: 28px 24px; color: var(--text);
  transition: border-color 0.2s ease, transform 0.2s ease;
}
.ob-picker-card:hover { border-color: var(--accent); transform: translateY(-2px); color: var(--text); }
.ob-picker-num { font-size: 11px; color: var(--text-dimmer); letter-spacing: 0.2em; }
.ob-picker-title { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 20px; letter-spacing: -0.02em; }
.ob-picker-desc { flex: 1; font-size: 14px; line-height: 1.55; color: var(--text-muted); }
.ob-picker-go { font-size: 11px; color: var(--accent); letter-spacing: 0.15em; text-transform: uppercase; }

/* As coordenadas chegam do JS em custom properties; aqui só se pinta.
   Nada disso existe sem a classe .fx-on na raiz, que o JS só adiciona em
   ponteiro fino e sem prefers-reduced-motion. */

/* 1. SPOTLIGHT NO CURSOR
   Fica atrás do conteúdo (z-index 1, mesma faixa do blueprint) — é um brilho
   no fundo, não um véu por cima do texto. */
.fx-spotlight {
  position: fixed; inset: 0; z-index: 1; pointer-events: none;
  opacity: 0; transition: opacity 0.4s ease;
  background: radial-gradient(
    620px circle at var(--fx-x, 50%) var(--fx-y, 50%),
    rgba(14, 165, 233, 0.10) 0%,
    rgba(14, 165, 233, 0.04) 35%,
    transparent 70%
  );
}
.fx-on .fx-spotlight { opacity: 1; }

/* 2. LINHAS DO BLUEPRINT ACENDENDO PERTO DO CURSOR
   Reaproveita a mesma marcação do .blueprint, então as linhas caem
   exatamente sobre as originais — só mais claras e recortadas num círculo
   em volta do cursor. */
.blueprint-glow > div { border-right-color: rgba(14, 165, 233, 0.5); }
