// Ponteiro grosso (dedo) não tem posição de repouso: um efeito que segue o
// cursor fica preso onde a pessoa tocou. Quem pediu menos movimento fica de
// fora também.
const FINO = window.matchMedia('(pointer: fine)');
const CALMO = window.matchMedia('(prefers-reduced-motion: reduce)');

export function initSpotlight() {
  if (CALMO.matches || !FINO.matches) return;

  const raiz = document.documentElement;
  raiz.classList.add('fx-on');

  let mx = 0, my = 0, pendente = false;

  // Toda a escrita acontece dentro de um rAF, então um movimento de mouse
  // nunca dispara mais de um layout por quadro.
  function pintar() {
    pendente = false;
    raiz.style.setProperty('--fx-x', mx + 'px');
    raiz.style.setProperty('--fx-y', my + 'px');
  }

  window.addEventListener('mousemove', function (e) {
    mx = e.clientX;
    my = e.clientY;
    if (!pendente) {
      pendente = true;
      requestAnimationFrame(pintar);
    }
  }, { passive: true });
}

