const FINO = window.matchMedia('(pointer: fine)');
const CALMO = window.matchMedia('(prefers-reduced-motion: reduce)');

const CARDS = '.diferencial-card, .service-card, .project-card, .about-card';

export function initCardsFx() {
  if (CALMO.matches) return;
  if (!FINO.matches) return initCardsNoToque();

  const raiz = document.documentElement;
  const cards = Array.prototype.slice.call(document.querySelectorAll(CARDS));
  raiz.classList.add('fx-on');

  let mx = 0, my = 0, pendente = false;

  function pintar() {
    pendente = false;
    // A borda de cada card precisa da posição relativa a ele, não à janela.
    // Só os cards visíveis entram na conta.
    cards.forEach(function (card) {
      const r = card.getBoundingClientRect();
      if (r.bottom < 0 || r.top > window.innerHeight) return;
      card.style.setProperty('--card-x', (mx - r.left) + 'px');
      card.style.setProperty('--card-y', (my - r.top) + 'px');
    });
  }

  window.addEventListener('mousemove', function (e) {
    mx = e.clientX;
    my = e.clientY;
    if (!pendente) {
      pendente = true;
      requestAnimationFrame(pintar);
    }
  }, { passive: true });
}

// Sem cursor, o gatilho é a entrada na tela: o card acende uma vez e apaga.
// Uma vez só — reacender a cada ida e volta deixaria a página piscando.
function initCardsNoToque() {
  const cards = document.querySelectorAll(CARDS);
  if (!cards.length || !('IntersectionObserver' in window)) return;

  document.documentElement.classList.add('fx-touch');

  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-lit');
      observer.unobserve(entry.target);
    });
  }, { rootMargin: '0px 0px -15% 0px', threshold: 0.2 });

  cards.forEach(function (card) { observer.observe(card); });
}

