export function initReveal() {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const alvos = document.querySelectorAll('[data-reveal]');
  if (!alvos.length || !('IntersectionObserver' in window)) return;

  document.documentElement.classList.add('reveal-on');

  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-revealed');
      observer.unobserve(entry.target);
    });
  }, {
    // Dispara um pouco antes de encostar na borda, para o movimento já estar
    // acontecendo quando o olho chega.
    rootMargin: '0px 0px -12% 0px',
    threshold: 0.05
  });

  alvos.forEach(function (alvo) {
    const filhos = alvo.querySelectorAll('[data-reveal-stagger] > *');
    filhos.forEach(function (filho, i) {
      filho.style.setProperty('--reveal-delay', (i * 70) + 'ms');
    });
    observer.observe(alvo);
  });
}

