componentes.js:
// A barra acompanha o que o navegador realmente já baixou — imagens e
// fontes — em vez de uma animação fingindo progresso.
//
// A régua tem dois pesos: 20% para o documento ficar interativo e 80% para os
// arquivos. Assim a barra não fica parada em 0 nem salta direto para o fim.

export function initLoader() {
  const el = document.getElementById('loader');
  if (!el) return;

  const numero = el.querySelector('.loader-num');
  const barra = el.querySelector('.loader-bar-fill');

  let mostrado = 0;   // a porcentagem que aparece na tela
  let alvo = 0;       // a porcentagem real, já medida
  let terminou = false;

  // Só as imagens que o navegador realmente vai buscar agora. As marcadas com
  // loading="lazy" nunca ficam completas fora da tela, e contá-las deixaria a
  // barra travada para sempre abaixo de 100.
  function paraContar() {
    return Array.prototype.slice.call(document.images).filter(function (i) {
      return i.loading !== 'lazy';
    });
  }

  function medir() {
    const imagens = paraContar();
    const prontas = imagens.filter(function (i) { return i.complete; }).length;
    const doc = document.readyState === 'complete' ? 1
      : document.readyState === 'interactive' ? 0.6 : 0.2;
    const arquivos = imagens.length ? prontas / imagens.length : 1;
    alvo = Math.min(100, Math.round(doc * 20 + arquivos * 80));
  }

  // O número sobe sozinho em direção ao alvo. Sem isso ele daria saltos secos
  // de 0 para 80 quando o cache já tem tudo.
  function passo() {
    medir();
    if (mostrado < alvo) mostrado += Math.max(1, Math.ceil((alvo - mostrado) / 6));
    if (mostrado > alvo) mostrado = alvo;

    numero.textContent = String(mostrado).padStart(3, '0');
    barra.style.transform = 'scaleX(' + (mostrado / 100) + ')';

    if (mostrado >= 100) return fechar();
    requestAnimationFrame(passo);
  }

  function fechar() {
    if (terminou) return;
    terminou = true;
    el.classList.add('is-done');
    document.documentElement.classList.remove('loading');
    // A classe cobre o caso de o hero ficar pronto depois deste aviso, o que
    // acontece quando as fontes demoram mais que o carregamento.
    document.documentElement.classList.add('loaded');
    document.dispatchEvent(new CustomEvent('loader:done'));
    // Só remove do DOM depois da transição de saída.
    setTimeout(function () { el.remove(); }, 900);
  }

  // O load é a palavra final: quando ele dispara, tudo o que era para vir já
  // veio.
  window.addEventListener('load', function () { alvo = 100; });

  // Rede de segurança: uma imagem que trave não pode prender a página.
  setTimeout(function () { alvo = 100; }, 6000);

  document.documentElement.classList.add('loading');
  requestAnimationFrame(passo);
}

componentes.demo:
// O loader some sozinho ao chegar em 100 e se remove do DOM — no preview
// isso deixaria a moldura vazia depois do primeiro ciclo. Aqui ele é
// remontado em looping, só pra dar tempo de ver.
const marcacao = document.getElementById('loader').outerHTML;
initLoader();
setInterval(function () {
  if (document.getElementById('loader')) return;
  document.body.insertAdjacentHTML('afterbegin', marcacao);
  initLoader();
}, 1400);

