// Competência como 'AAAA-MM'. A aritmética é feita em número de mês (0-11),
// que é o que faz dezembro virar janeiro sem caso especial.
function deslocar(mes, passo) {
  const [ano, m] = mes.split('-').map(Number)
  const d = new Date(ano, m - 1 + passo, 1)
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')
}

function rotulo(mes) {
  const [ano, m] = mes.split('-').map(Number)
  const texto = new Date(ano, m - 1, 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })
  return texto.charAt(0).toUpperCase() + texto.slice(1)
}

export function iniciarSeletorMes(raiz, atual, aoMudar) {
  const label = raiz.querySelector('.bs-mes-label')
  const hoje = raiz.querySelector('.bs-mes-hoje')

  function render() {
    const mes = raiz.dataset.mes
    label.textContent = rotulo(mes)
    // O "Hoje" só existe fora do mês corrente: botão inerte ensina o usuário
    // a ignorar o canto da tela.
    hoje.hidden = mes === atual
    aoMudar?.(mes)
  }

  raiz.querySelectorAll('.bs-mes-seta').forEach((btn) => {
    btn.addEventListener('click', () => {
      raiz.dataset.mes = deslocar(raiz.dataset.mes, Number(btn.dataset.passo))
      render()
    })
  })
  hoje.addEventListener('click', () => {
    raiz.dataset.mes = atual
    render()
  })

  render()
}

