const CHAVE = 'baseJL.sidebarCollapsed'

export function iniciarSidebar(raiz) {
  const toggle = raiz.querySelector('.bs-side-toggle')

  function aplicar(recolhida) {
    raiz.classList.toggle('bs-recolhida', recolhida)
    toggle.setAttribute('aria-label', recolhida ? 'Expandir menu' : 'Recolher menu')
    // Preferência, não estado de tela: sem persistir, o menu reabre sozinho
    // a cada navegação.
    localStorage.setItem(CHAVE, recolhida ? '1' : '0')
  }

  toggle.addEventListener('click', () => aplicar(!raiz.classList.contains('bs-recolhida')))

  // Marcar o item clicado como ativo é o que a rota faz no app.
  raiz.querySelectorAll('.bs-side-item').forEach((item) => {
    item.addEventListener('click', () => {
      raiz.querySelectorAll('.bs-side-item').forEach((i) => i.classList.remove('bs-side-ativo'))
      item.classList.add('bs-side-ativo')
    })
  })

  aplicar(localStorage.getItem(CHAVE) === '1')
}

