body { display: flex; align-items: flex-end; min-height: 100vh; margin: 0; }

.bs-tab {
  display: flex; gap: 4px; width: 100%;
  /* Onze destinos não cabem em 375px: em vez de espremer o alvo de toque
     abaixo de 44px, a barra rola na horizontal. */
  overflow-x: auto; scrollbar-width: none;
  height: 84px; padding: 8px 8px 24px;
  border-top: 1px solid var(--border); background: var(--bg-surface);
}
