componentes.js:
export function iniciarTabBar(raiz) {
  raiz.querySelectorAll('.bs-tab-item').forEach((item) => {
    item.addEventListener('click', () => {
      raiz.querySelectorAll('.bs-tab-item').forEach((i) => {
        i.classList.remove('bs-tab-ativo')
        i.removeAttribute('aria-current')
      })
      item.classList.add('bs-tab-ativo')
      item.setAttribute('aria-current', 'page')
      // Aba escolhida no fim da rolagem some pela metade sem isso.
      item.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' })
    })
  })
}

