.bs-btn-sec:hover { border-color: var(--accent); }
.bs-btn-pri:hover { background: #38bdf8; }

:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
