  background: var(--bg-surface);
}
.bs-sheet::-webkit-scrollbar { display: none; }

/* Não arrasta nada: é a affordance de "isto veio de baixo", e por isso some
   no desktop, onde o painel não vem de lugar nenhum. */
.bs-sheet-puxador {
  width: 36px; height: 4px; margin: 0 auto 16px;
