const OLHO = '<path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0"/><circle cx="12" cy="12" r="3"/>'
const OLHO_CORTE = '<path d="M10.733 5.076a10.744 10.744 0 0 1 11.205 6.575 1 1 0 0 1 0 .696 10.747 10.747 0 0 1-1.444 2.49"/><path d="M14.084 14.158a3 3 0 0 1-4.242-4.242"/><path d="M17.479 17.499a10.75 10.75 0 0 1-15.417-5.151 1 1 0 0 1 0-.696 10.75 10.75 0 0 1 4.446-5.143"/><path d="m2 2 20 20"/>'
const CHECK = '<path d="M20 6 9 17l-5-5"/>'

/**
 * @param raiz elemento .bs-segredo
 * @param carregar () => Promise<string>. O valor nunca vem do HTML: é esta
 *   função que busca (e decifra) no clique, e o resultado é descartado ao
 *   ocultar. Guardar o segredo num data-* devolveria ele pro DOM, que é
 *   exatamente o que a máscara evita.
 */
export function iniciarSegredo(raiz, carregar) {
  const valor = raiz.querySelector('.bs-segredo-valor')
  const olho = raiz.querySelector('.bs-segredo-olho')
  const copiar = raiz.querySelector('.bs-segredo-copiar')
  const mascara = valor.textContent
  let revelado = false

  const obter = () => carregar()

  olho.addEventListener('click', async () => {
    if (revelado) {
      // Ocultar joga o texto real fora do DOM de novo.
      valor.textContent = mascara
      valor.classList.add('bs-oculto')
      olho.querySelector('svg').innerHTML = OLHO
      olho.setAttribute('aria-label', 'Revelar')
      revelado = false
      return
    }
    olho.disabled = true
    valor.textContent = await obter()
    valor.classList.remove('bs-oculto')
    olho.querySelector('svg').innerHTML = OLHO_CORTE
    olho.setAttribute('aria-label', 'Ocultar')
    olho.disabled = false
    revelado = true
  })

  // Copiar sem revelar: é o caminho mais comum, e o segredo não precisa
  // passar pela tela pra chegar no outro sistema.
  copiar.addEventListener('click', async () => {
    copiar.disabled = true
    await navigator.clipboard.writeText(await obter())
    const svg = copiar.querySelector('svg')
    const antes = svg.innerHTML
    svg.innerHTML = CHECK
    copiar.disabled = false
    setTimeout(() => { svg.innerHTML = antes }, 1500)
  })
}

