const brl = (v) =>
  (v < 0 ? '- ' : '') + 'R$ ' + Math.abs(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })

// Canvas não enxerga classe nem variável aplicada, mas lê o valor da custom
// property — assim a paleta continua morando num lugar só.
const token = (nome) => getComputedStyle(document.documentElement).getPropertyValue(nome).trim()

const MESES = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez']

/**
 * @param canvas <canvas> dentro de um container de altura fixa
 * @param dados { fontes: { rotulo, token, valores[12] }[], despesa: number[12] }
 */
export function iniciarGraficoAnual(canvas, dados) {
  const saldo = dados.despesa.map((d, i) => dados.fontes.reduce((s, f) => s + f.valores[i], 0) - d)

  new Chart(canvas, {
    type: 'bar',
    data: {
      labels: MESES,
      datasets: [
        ...dados.fontes.map((f) => ({
          type: 'bar',
          label: f.rotulo,
          data: f.valores,
          backgroundColor: token(f.token),
          // Entrada e despesa em pilhas separadas: empilhar as duas juntas
          // daria um total sem significado nenhum.
          stack: 'entrada',
          borderRadius: 2,
          maxBarThickness: 22,
        })),
        {
          type: 'bar',
          label: 'Despesa',
          data: dados.despesa,
          backgroundColor: token('--danger'),
          stack: 'despesa',
          borderRadius: 2,
          maxBarThickness: 22,
        },
        {
          type: 'line',
          label: 'Saldo',
          data: saldo,
          borderColor: token('--accent'),
          backgroundColor: token('--accent'),
          pointBackgroundColor: token('--accent'),
          fill: false,
          tension: 0.3,
          pointRadius: 3,
          borderWidth: 2,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      // Mostra as seis séries do mês de uma vez, sem exigir mira no ponto.
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${brl(ctx.parsed.y ?? 0)}` } },
      },
      scales: {
        x: {
          stacked: true,
          ticks: { font: { size: 10 }, maxRotation: 0, autoSkip: false, color: token('--text-muted') },
          grid: { display: false },
        },
        y: {
          stacked: true,
          ticks: { font: { size: 10 }, color: token('--text-muted'), callback: (v) => brl(Number(v)) },
          grid: { color: 'rgba(148, 163, 184, 0.12)' },
        },
      },
    },
  })
}
